    border=cnt[1][0]
    m=(a==border)
    rs,cS=m.nonzero()
    r0,r1,c0,c1=rs.min(),rs.max(),cS.min(),cS.max()
    res=a.copy()
    for i,j in zip(*((~m)&(a!=bg)).nonzero()):
        cr=(r0+r1)/2; cc=(c0+c1)/2
        if i<cr and j<cc: tgt=('down','right')
        elif i<cr and j>cc: tgt=('down','left')
        elif i>cr and j<cc: tgt=('up','right')
        else: tgt=('up','left')
        crn=(r0 if tgt[0]=='up' else r1, c0 if tgt[1]=='left' else c1)
        nr,nj=crn[0]+(1 if tgt[0]=='down' else -1), crn[1]+(1 if tgt[1]=='right' else -1)
        res[nr,nj]=a[i,j]; res[i,j]=bg
